    theme?: ColorTheme;
    density?: Density;
    interactionMode?: InteractionMode;
    style?: ScopeStyle;
}
/** A scoped visual root. System theme is resolved by CSS, never browser reads in render. */
export declare const ThemeScope: import("react").ForwardRefExoticComponent<ThemeScopeProps & import("react").RefAttributes<HTMLDivElement>>;
/** Internal portal attributes. Layout styles never propagate to overlays. */
export declare function useOverlayScope(): {
    "data-sgui-scope": string;
    "data-sgui-theme": ColorTheme;
    "data-sgui-density": Density;
    "data-sgui-interaction": InteractionMode;
